import React, { useState, useEffect, useRef } from 'react';

const VoiceWeb = () => {
  const [messages, setMessages] = useState([]);
  const [isLive, setIsLive] = useState(false);
  const [inputValue, setInputValue] = useState('');

  // CRITICAL: Using Ref so the step can NEVER be reset by a re-render
  const stepRef = useRef(0); 
  const serviceRef = useRef('');

  const scrollRef = useRef(null);
  const recognitionRef = useRef(null);

  const services = ["1. Booking", "2. Status", "3. Check-in", "4. Baggage", "5. Refund", "6. Lounge", "7. Assistance", "8. Loyalty", "9. Agent", "10. Info"];

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages]);

  const speak = (text, nextStep) => {
    window.speechSynthesis.cancel();
    const msg = new SpeechSynthesisUtterance(text);
    msg.onstart = () => setMessages(prev => [...prev, { sender: "Voice Web", text }]);
    msg.onend = () => {
      if (nextStep !== undefined) stepRef.current = nextStep;
      if (stepRef.current < 5) startListening(); 
    };
    window.speechSynthesis.speak(msg);
  };

  const startListening = () => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) return;
    if (recognitionRef.current) recognitionRef.current.stop();

    recognitionRef.current = new SpeechRecognition();
    recognitionRef.current.lang = 'en-IN';
    recognitionRef.current.onstart = () => setIsLive(true);
    recognitionRef.current.onend = () => setIsLive(false);
    recognitionRef.current.onresult = (e) => handleLogic(e.results[0][0].transcript);
    recognitionRef.current.start();
  };

  const handleLogic = (input) => {
    if (!input) return;
    const text = input.toLowerCase().trim();
    setMessages(prev => [...prev, { sender: "You", text: input }]);

    // STEP 0: LANGUAGE SELECTION
    if (stepRef.current === 0) {
      stepRef.current = 1; // IMMEDIATELY LOCK STEP 1
      speak("Language confirmed. Select your service from our list.", 1);
      setMessages(prev => [...prev, { sender: "System", text: services.join(", ") }]);
      return; // Stop execution here
    } 

    // STEP 1: SERVICE SELECTION (Fixed matching)
    if (stepRef.current === 1) {
      if (text.includes('booking') || text.includes('one') || text.includes('1')) {
        serviceRef.current = "Booking";
        speak("Booking service selected. First, what is your departure city?", 2);
      } else if (text.includes('status') || text.includes('two') || text.includes('2')) {
        serviceRef.current = "Status";
        speak("Status service selected. Please provide your PNR number.", 2);
      } else {
        speak("I heard " + input + ". Please choose a service like Booking or Status.", 1);
      }
      return;
    }

    // STEP 2: QUESTION 1 -> QUESTION 2
    if (stepRef.current === 2) {
      speak("Understood. Second question: What is your preferred travel date and time?", 3);
      return;
    }

    // STEP 3: QUESTION 2 -> QUESTION 3
    if (stepRef.current === 3) {
      speak("Got it. Third question: Would you like to add any special meals or extra baggage?", 4);
      return;
    }

    // STEP 4: QUESTION 3 -> END
    if (stepRef.current === 4) {
      speak("Thank you for all the details. Your request is being processed. Thanks for choosing SkySync. Your journey really matters a lot to us.", 5);
      return;
    }
  };

  const initAssistant = () => {
    stepRef.current = 0;
    setMessages([]);
    speak("Welcome to SkySync. Please select your preferred language.");
  };

  return (
    <div style={{ height: '100vh', display: 'flex', flexDirection: 'column', background: '#f4f7fa', overflow: 'hidden', fontFamily: 'sans-serif' }}>

      {/* HEADER */}
      <div style={{ padding: '12px 40px', background: 'white', display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #eee' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <div style={{ background: '#2563eb', color: 'white', padding: '5px 8px', borderRadius: '8px' }}>✈️</div>
          <b style={{ color: '#1e3a8a' }}>SKY-SYNC AI</b>
        </div>
        <div style={{ display: 'flex', background: '#f1f5f9', borderRadius: '25px', padding: '4px' }}>
          <button style={{ padding: '6px 20px', border: 'none', background: 'transparent' }}>Voice Call</button>
          <button style={{ padding: '6px 20px', border: 'none', background: '#2563eb', color: 'white', borderRadius: '20px' }}>Voice Web</button>
        </div>
      </div>

      <div style={{ flex: 1, display: 'grid', gridTemplateColumns: '280px 1fr 300px', gap: '20px', padding: '20px', overflow: 'hidden' }}>

        {/* LEFT COLUMN */}
        <div style={{ background: 'white', borderRadius: '20px', padding: '15px', border: '1px solid #e2e8f0', overflowY: 'auto' }}>
          <h5 style={{ fontSize: '13px', color: '#64748b', marginBottom: '10px' }}>FLIGHT SERVICES</h5>
          {services.map((s, i) => (
            <div key={i} style={{ padding: '8px', fontSize: '12px', borderBottom: '1px solid #f1f5f9' }}>{s}</div>
          ))}
          <div style={{ marginTop: '20px', padding: '15px', background: '#1e293b', borderRadius: '15px', color: 'white' }}>
            <div style={{ fontSize: '10px', opacity: 0.8 }}>Terminal Map</div>
            <div style={{ fontSize: '13px', marginTop: '5px' }}>Gate T3-A12 📍</div>
          </div>
        </div>

        {/* CENTER COLUMN */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', overflow: 'hidden' }}>
          <div style={{ flex: 1, background: 'white', borderRadius: '24px', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', border: '1px solid #e2e8f0' }}>
             <div onClick={initAssistant} style={{ width: '130px', height: '130px', borderRadius: '50%', background: isLive ? '#2563eb' : '#f1f5f9', display: 'flex', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', boxShadow: isLive ? '0 0 20px rgba(37, 99, 235, 0.4)' : 'none' }}>
                <span style={{ fontSize: '45px' }}>🎙️</span>
             </div>
             <p style={{ marginTop: '15px', fontSize: '12px', fontWeight: 'bold', color: isLive ? '#2563eb' : '#94a3b8' }}>
               {isLive ? "LISTENING..." : "TAP MIC TO START"}
             </p>
          </div>

          <div style={{ height: '280px', background: 'white', borderRadius: '24px', padding: '20px', display: 'flex', flexDirection: 'column', overflow: 'hidden', border: '1px solid #e2e8f0' }}>
            <b style={{ fontSize: '13px', color: '#1e3a8a', marginBottom: '10px' }}>Live Transcript</b>
            <div ref={scrollRef} style={{ flex: 1, overflowY: 'auto' }}>
              {messages.map((m, i) => (
                <div key={i} style={{ marginBottom: '10px', padding: '12px', borderRadius: '15px', background: m.sender === "You" ? '#eff6ff' : '#f8fafc', border: '1px solid #f1f5f9' }}>
                  <span style={{ fontSize: '10px', fontWeight: 'bold', color: '#2563eb', display: 'block' }}>{m.sender}</span>
                  <span style={{ fontSize: '12px' }}>{m.text}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* RIGHT COLUMN */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          <div style={{ background: 'linear-gradient(135deg, #2563eb, #1d4ed8)', color: 'white', padding: '25px', borderRadius: '24px', textAlign: 'center' }}>
            <div style={{ fontSize: '32px', fontWeight: 'bold' }}>28°C</div>
            <div style={{ fontSize: '13px' }}>Hyderabad - Sunny</div>
          </div>
          <div style={{ background: 'white', borderRadius: '20px', padding: '15px', border: '1px solid #e2e8f0' }}>
            <h5 style={{ margin: '0 0 10px 0', fontSize: '12px' }}>QUICK HELP</h5>
            {['Track Flight', 'Baggage Help', 'Lounge Access', 'Terminal Map'].map((item, idx) => (
              <button key={idx} style={{ width: '100%', padding: '8px', marginBottom: '5px', borderRadius: '8px', border: '1px solid #f1f5f9', background: 'none', textAlign: 'left', fontSize: '11px' }}>🔗 {item}</button>
            ))}
          </div>
        </div>
      </div>

      {/* FOOTER */}
      <div style={{ background: 'white', padding: '15px 40px', borderTop: '1px solid #e2e8f0', display: 'flex', gap: '15px' }}>
        <input 
          type="text" 
          placeholder="Speak or type selection..." 
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleLogic(inputValue)}
          style={{ flex: 1, padding: '12px 25px', borderRadius: '30px', border: '1px solid #e2e8f0', fontSize: '13px' }} 
        />
        <button onClick={() => handleLogic(inputValue)} style={{ background: '#2563eb', color: 'white', border: 'none', padding: '0 35px', borderRadius: '30px', fontWeight: 'bold' }}>SEND</button>
      </div>
    </div>
  );
};

export default VoiceWeb;
